def grads_of(expr, x, y):
    """Build one of a few expressions, call backward(), report value and grads."""
    x, y = Value(x), Value(y)
    if expr == "reuse":
        L = x * x + x
    elif expr == "chain":
        L = (x * y + x) * y
    elif expr == "diamond":
        a = x * y
        L = (a + a) * a
    else:
        L = x * y - y * 3
    L.backward()
    return [L.data, x.grad, y.grad]

