def activation_grads(op, x):
    """Apply one operation to Value(x), backpropagate, return [output, d output / dx]."""
    v = Value(x)
    if op == "tanh":
        out = v.tanh()
    elif op == "relu":
        out = v.relu()
    elif op == "cube":
        out = v ** 3
    elif op == "inverse":
        out = v ** -1
    else:  # "squash": tanh(2x + 1) / 2
        out = (v * 2 + 1).tanh() / 2
    out.backward()
    return [out.data, v.grad]

